// CLEAN CODE: Defensive programming with boundary validation.
// This code survives hacker-level boundary testing.

public class PlayerHealth : MonoBehaviour
{
    [SerializeField] private int maxHealth = 100;
    [SerializeField] private int currentHealth;
    [SerializeField] private bool isInvulnerable = false;
    [SerializeField] private bool isDead = false;

    public int CurrentHealth => currentHealth;
    public int MaxHealth => maxHealth;
    public bool IsDead => isDead;

    private void Awake()
    {
        currentHealth = maxHealth;
    }

    public void TakeDamage(int damage)
    {
        // Defensive: reject invalid states
        if (isDead) return;
        if (isInvulnerable) return;
        if (damage < 0)
        {
            Debug.LogWarning($"TakeDamage called with negative value: {damage}. Ignoring.");
            return;
        }

        // Apply damage with clamping
        currentHealth = Mathf.Max(0, currentHealth - damage);

        // Trigger events for UI, sound, particles
        OnHealthChanged?.Invoke(currentHealth, maxHealth);

        if (currentHealth <= 0)
        {
            Die();
        }
    }

    public void Heal(int amount)
    {
        if (isDead) return;
        if (amount < 0)
        {
            Debug.LogWarning($"Heal called with negative value: {amount}. Ignoring.");
            return;
        }

        // Clamp to max health — prevents overflow and UI glitches
        currentHealth = Mathf.Min(maxHealth, currentHealth + amount);
        OnHealthChanged?.Invoke(currentHealth, maxHealth);
    }

    public void SetInvulnerable(bool invulnerable)
    {
        isInvulnerable = invulnerable;
    }

    private void Die()
    {
        if (isDead) return;  // Prevent double-death
        isDead = true;

        OnDied?.Invoke();

        // Disable player controls, trigger death animation,
        // show game over UI after delay...
        StartCoroutine(DeathSequence());
    }

    private IEnumerator DeathSequence()
    {
        // Wait for death animation
        yield return new WaitForSeconds(2f);

        // Show game over screen
        GameOverManager.Instance?.ShowGameOver();
    }

    // Events for decoupled systems (UI, audio, achievements)
    public event System.Action<int, int> OnHealthChanged;
    public event System.Action OnDied;
}
